     8	import java.util.concurrent.CopyOnWriteArrayList;
     9	
    10	import com.sun.net.httpserver.HttpServer;
    11	
    12	
    13	public final class FakeTranslog {
    14	
    15	    private static final FakeTranslog INSTANCE = new FakeTranslog();
    16	
    17	    private final HttpServer server;
    18	    private final List<String> queries = new CopyOnWriteArrayList<>();
    19	    private volatile int status;
    20	    private volatile String body;
    21	    private volatile long delayMillis;
    22	
    23	    private FakeTranslog() {
    24	        try {
    25	            server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    26	        } catch (IOException e) {
    27	            throw new IllegalStateException(e);
    28	        }
    29	        server.createContext("/v2/quote", exchange -> {
    30	            queries.add(exchange.getRequestURI().getQuery());
    31	            try {
    32	                Thread.sleep(delayMillis);
    33	            } catch (InterruptedException e) {
    34	                Thread.currentThread().interrupt();
    35	            }
    36	            byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
    37	            exchange.getResponseHeaders().add("Content-Type", "application/json");
    38	            exchange.sendResponseHeaders(status, bytes.length);
    39	            try (OutputStream out = exchange.getResponseBody()) {
    40	                out.write(bytes);
    41	            } catch (IOException ignored) {
    42	
    43	            }
    44	        });
    45	        server.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
    46	        server.start();
    47	        reset();
    48	    }
    49	
    50	    public static FakeTranslog get() {
    51	        return INSTANCE;
    52	    }
    53	
    54	    public String url() {
    55	        return "http://127.0.0.1:" + server.getAddress().getPort();
    56	    }
    57	
    58	    public void reset() {
    59	        respond(200, "{ \"price_cents\": 2000, \"eta_hours\": 24 }");
    60	        delayMillis = 0;
    61	        queries.clear();
    62	    }
    63	
    64	    public void quote(int priceCents, int etaHours) {
    65	        respond(200, "{ \"price_cents\": " + priceCents + ", \"eta_hours\": " + etaHours + " }");
    66	    }
    67	
    68	    public void respond(int status, String body) {
    69	        this.status = status;
    70	        this.body = body;
    71	    }
    72	
    73	    public void delay(long millis) {
    74	        this.delayMillis = millis;
    75	    }
    76	
    77	    public List<String> queries() {
    78	        return queries;
    79	    }
    80	}
